-- Card rules text translations, part 4: bosses and creatures with their own triggers or
-- abilities. «self» is the card's own (translated) name, «zone:<key>» a zone's name.
return {
    { en = "Airborne. When Balnazzar enters the battlefield, gain control of target opposing creature with power 4 or less.", de = "Fliegend. Wenn «self» ins Spiel kommt, übernimm die Kontrolle über eine gegnerische Kreatur deiner Wahl mit höchstens 4 Stärke.", fr = "Aérien. Quand «self» arrive sur le champ de bataille, prenez le contrôle d'une créature adverse ciblée de force 4 ou moins.", es = "Aérea. Cuando «self» entre al campo de batalla, toma el control de una criatura enemiga objetivo con 4 o menos de fuerza.", zh = "飞行。当«self»进入战场时，获得目标力量不大于4的敌方生物的控制权。", it = "Volante. Quando «self» entra nel campo di battaglia, prendi il controllo di una creatura avversaria bersaglio con forza 4 o inferiore." },
    { en = "Airborne. Whenever Eranikus deals combat damage to a creature, tap that creature and it does not untap during its controller's next untap step.", de = "Fliegend. Immer wenn «self» einer Kreatur Kampfschaden zufügt, tappe jene Kreatur; sie enttappt im nächsten Enttappsegment ihres Beherrschers nicht.", fr = "Aérien. Chaque fois que «self» inflige des dégâts de combat à une créature, engagez cette créature ; elle ne se dégage pas lors de la prochaine étape de dégagement de son contrôleur.", es = "Aérea. Siempre que «self» inflija daño de combate a una criatura, gira esa criatura; no se endereza en el próximo paso de enderezar de su controlador.", zh = "飞行。每当«self»对一个生物造成战斗伤害时，将该生物横置；它在其操控者的下一个重置步骤中不会重置。", it = "Volante. Ogni volta che «self» infligge danni da combattimento a una creatura, tappa quella creatura; non stappa nel prossimo passo di stap del suo controllore." },
    { en = "Anti-Air. When Hemet Nesingwary enters the battlefield, deal 2 damage to each enemy Beast. Other Stranglethorn Vale creatures you control get +1/+0.", de = "Luftabwehr. Wenn «self» ins Spiel kommt, füge jedem gegnerischen Wildtier 2 Schaden zu. Deine anderen Kreaturen aus «zone:Stranglethorn Vale» erhalten +1/+0.", fr = "Anti-aérien. Quand «self» arrive sur le champ de bataille, infligez 2 points de dégâts à chaque Bête adverse. Les autres créatures de «zone:Stranglethorn Vale» que vous contrôlez gagnent +1/+0.", es = "Antiaérea. Cuando «self» entre al campo de batalla, inflige 2 de daño a cada Bestia enemiga. Tus otras criaturas de «zone:Stranglethorn Vale» obtienen +1/+0.", zh = "防空。当«self»进入战场时，对每个敌方野兽造成2点伤害。你操控的其他«zone:Stranglethorn Vale»生物获得+1/+0。", it = "Antiaerea. Quando «self» entra nel campo di battaglia, infliggi 2 danni a ogni Bestia avversaria. Le altre creature di «zone:Stranglethorn Vale» che controlli ottengono +1/+0." },
    { en = "Anti-Air. {T}: Tap target creature. It does not untap during its controller's next untap step.", de = "Luftabwehr. {T}: Tappe eine Kreatur deiner Wahl. Sie enttappt im nächsten Enttappsegment ihres Beherrschers nicht.", fr = "Anti-aérien. {T} : engagez une créature ciblée. Elle ne se dégage pas lors de la prochaine étape de dégagement de son contrôleur.", es = "Antiaérea. {T}: gira una criatura objetivo. No se endereza en el próximo paso de enderezar de su controlador.", zh = "防空。{T}：横置目标生物。它在其操控者的下一个重置步骤中不会重置。", it = "Antiaerea. {T}: tappa una creatura bersaglio. Non stappa nel prossimo passo di stap del suo controllore." },
    { en = "Brutish. Aku'mai can block up to two creatures each combat.", de = "Brachial. «self» kann in jedem Kampf bis zu zwei Kreaturen blocken.", fr = "Brutal. «self» peut bloquer jusqu'à deux créatures à chaque combat.", es = "Brutal. «self» puede bloquear hasta dos criaturas en cada combate.", zh = "蛮力。«self»每次战斗最多可以阻挡两个生物。", it = "Brutale. «self» può bloccare fino a due creature in ogni combattimento." },
    { en = "Brutish. All other creatures lose and cannot gain Quick.", de = "Brachial. Alle anderen Kreaturen verlieren Flink und können es nicht erhalten.", fr = "Brutal. Toutes les autres créatures perdent Rapide et ne peuvent pas l'acquérir.", es = "Brutal. Todas las demás criaturas pierden Rápida y no pueden obtenerla.", zh = "蛮力。所有其他生物失去迅捷且无法获得迅捷。", it = "Brutale. Tutte le altre creature perdono Rapida e non possono ottenerla." },
    { en = "Brutish. Ukorz gets +3/+0 as long as your life total is 10 or less.", de = "Brachial. «self» erhält +3/+0, solange du 10 oder weniger Leben hast.", fr = "Brutal. «self» gagne +3/+0 tant que vous avez 10 points de vie ou moins.", es = "Brutal. «self» obtiene +3/+0 mientras tengas 10 o menos de vida.", zh = "蛮力。只要你的生命值不大于10，«self»便获得+3/+0。", it = "Brutale. «self» ottiene +3/+0 finché hai 10 o meno punti vita." },
    { en = "Brutish. When Ramstein the Gorger enters the battlefield, deal 2 damage to each enemy creature. Other Undead you control get +1/+1.", de = "Brachial. Wenn «self» ins Spiel kommt, füge jeder gegnerischen Kreatur 2 Schaden zu. Deine anderen Untoten erhalten +1/+1.", fr = "Brutal. Quand «self» arrive sur le champ de bataille, infligez 2 points de dégâts à chaque créature adverse. Les autres Morts-vivants que vous contrôlez gagnent +1/+1.", es = "Brutal. Cuando «self» entre al campo de batalla, inflige 2 de daño a cada criatura enemiga. Tus otros No-muertos obtienen +1/+1.", zh = "蛮力。当«self»进入战场时，对每个敌方生物造成2点伤害。你操控的其他亡灵获得+1/+1。", it = "Brutale. Quando «self» entra nel campo di battaglia, infliggi 2 danni a ogni creatura avversaria. Gli altri Non Morti che controlli ottengono +1/+1." },
    { en = "Brutish. When Wyrmthalak enters the battlefield, deal 3 damage to all opposing creatures.", de = "Brachial. Wenn «self» ins Spiel kommt, füge allen gegnerischen Kreaturen 3 Schaden zu.", fr = "Brutal. Quand «self» arrive sur le champ de bataille, infligez 3 points de dégâts à toutes les créatures adverses.", es = "Brutal. Cuando «self» entre al campo de batalla, inflige 3 de daño a todas las criaturas enemigas.", zh = "蛮力。当«self»进入战场时，对所有敌方生物造成3点伤害。", it = "Brutale. Quando «self» entra nel campo di battaglia, infliggi 3 danni a tutte le creature avversarie." },
    { en = "Brutish. Whenever King Gordok attacks, he gets +2/+0 until end of turn.", de = "Brachial. Immer wenn «self» angreift, erhält er bis zum Ende des Zuges +2/+0.", fr = "Brutal. Chaque fois que «self» attaque, il gagne +2/+0 jusqu'à la fin du tour.", es = "Brutal. Siempre que «self» ataque, obtiene +2/+0 hasta el final del turno.", zh = "蛮力。每当«self»攻击时，它获得+2/+0直到回合结束。", it = "Brutale. Ogni volta che «self» attacca, ottiene +2/+0 fino alla fine del turno." },
    { en = "Brutish. Whenever Theradras deals combat damage to a player, destroy target non-basic land that player controls.", de = "Brachial. Immer wenn «self» einem Spieler Kampfschaden zufügt, zerstöre ein Gebet dieses Spielers.", fr = "Brutal. Chaque fois que «self» inflige des dégâts de combat à un joueur, détruisez une Prière que ce joueur contrôle.", es = "Brutal. Siempre que «self» inflija daño de combate a un jugador, destruye una Plegaria que controle ese jugador.", zh = "蛮力。每当«self»对一名玩家造成战斗伤害时，消灭该玩家操控的一张祈祷。", it = "Brutale. Ogni volta che «self» infligge danni da combattimento a un giocatore, distruggi una Preghiera controllata da quel giocatore." },
    { en = "Drain. When Princess Moira Bronzebeard enters the battlefield, each creature you control regains 4 health. Other Dark Iron you control get +1/+1.", de = "Entzug. Wenn «self» ins Spiel kommt, erhält jede Kreatur, die du kontrollierst, 4 Leben zurück. Deine anderen Dunkeleisenzwerge erhalten +1/+1.", fr = "Drain. Quand «self» arrive sur le champ de bataille, chaque créature que vous contrôlez regagne 4 points de vie. Les autres Sombrefer que vous contrôlez gagnent +1/+1.", es = "Drenaje. Cuando «self» entre al campo de batalla, cada criatura que controles recupera 4 de salud. Tus otros Hierro Negro obtienen +1/+1.", zh = "吸取。当«self»进入战场时，你操控的每个生物恢复4点生命。你操控的其他黑铁获得+1/+1。", it = "Risucchio. Quando «self» entra nel campo di battaglia, ogni creatura che controlli recupera 4 punti salute. Gli altri Ferroscuro che controlli ottengono +1/+1." },
    { en = "Drain. When Whitemane dies, return another target creature from your graveyard to the battlefield.", de = "Entzug. Wenn «self» stirbt, bringe eine andere Kreatur deiner Wahl aus deinem Friedhof aufs Schlachtfeld zurück.", fr = "Drain. Quand «self» meurt, renvoyez une autre créature ciblée de votre cimetière sur le champ de bataille.", es = "Drenaje. Cuando «self» muera, devuelve otra criatura objetivo de tu cementerio al campo de batalla.", zh = "吸取。当«self»死亡时，将你坟墓场中另一个目标生物移回战场。", it = "Risucchio. Quando «self» muore, riporta un'altra creatura bersaglio dal tuo cimitero sul campo di battaglia." },
    { en = "Drain. Whenever an opposing creature dies, its controller loses 2 life.", de = "Entzug. Immer wenn eine gegnerische Kreatur stirbt, verliert ihr Beherrscher 2 Leben.", fr = "Drain. Chaque fois qu'une créature adverse meurt, son contrôleur perd 2 points de vie.", es = "Drenaje. Siempre que muera una criatura enemiga, su controlador pierde 2 de vida.", zh = "吸取。每当一个敌方生物死亡时，其操控者失去2点生命。", it = "Risucchio. Ogni volta che una creatura avversaria muore, il suo controllore perde 2 punti vita." },
    { en = "Fatal. When Bloodmage Thalnos dies, draw a card.", de = "Tödlich. Wenn «self» stirbt, ziehe eine Karte.", fr = "Fatal. Quand «self» meurt, piochez une carte.", es = "Letal. Cuando «self» muera, roba una carta.", zh = "致命。当«self»死亡时，抓一张牌。", it = "Fatale. Quando «self» muore, pesca una carta." },
    { en = "Fatal. {T}: You gain 4 life.", de = "Tödlich. {T}: Du erhältst 4 Leben.", fr = "Fatal. {T} : vous gagnez 4 points de vie.", es = "Letal. {T}: ganas 4 de vida.", zh = "致命。{T}：你获得4点生命。", it = "Fatale. {T}: guadagni 4 punti vita." },
    { en = "Other Scarlet Monastery creatures you control get +1/+1. When Azshir the Sleepless dies, return a creature card from your graveyard to the battlefield.", de = "Deine anderen Kreaturen aus «zone:Scarlet Monastery» erhalten +1/+1. Wenn «self» stirbt, bringe eine Kreaturenkarte aus deinem Friedhof aufs Schlachtfeld zurück.", fr = "Les autres créatures de «zone:Scarlet Monastery» que vous contrôlez gagnent +1/+1. Quand «self» meurt, renvoyez une carte de créature de votre cimetière sur le champ de bataille.", es = "Tus otras criaturas de «zone:Scarlet Monastery» obtienen +1/+1. Cuando «self» muera, devuelve una carta de criatura de tu cementerio al campo de batalla.", zh = "你操控的其他«zone:Scarlet Monastery»生物获得+1/+1。当«self»死亡时，将一张生物牌从你的坟墓场移回战场。", it = "Le altre creature di «zone:Scarlet Monastery» che controlli ottengono +1/+1. Quando «self» muore, riporta una carta creatura dal tuo cimitero sul campo di battaglia." },
    { en = "Other Shadowfang Keep creatures you control get +1/+1. When Deathsworn Captain dies, deal 2 damage to each enemy creature.", de = "Deine anderen Kreaturen aus «zone:Shadowfang Keep» erhalten +1/+1. Wenn «self» stirbt, füge jeder gegnerischen Kreatur 2 Schaden zu.", fr = "Les autres créatures de «zone:Shadowfang Keep» que vous contrôlez gagnent +1/+1. Quand «self» meurt, infligez 2 points de dégâts à chaque créature adverse.", es = "Tus otras criaturas de «zone:Shadowfang Keep» obtienen +1/+1. Cuando «self» muera, inflige 2 de daño a cada criatura enemiga.", zh = "你操控的其他«zone:Shadowfang Keep»生物获得+1/+1。当«self»死亡时，对每个敌方生物造成2点伤害。", it = "Le altre creature di «zone:Shadowfang Keep» che controlli ottengono +1/+1. Quando «self» muore, infliggi 2 danni a ogni creatura avversaria." },
    { en = "Quick. Herod attacks each combat if able.", de = "Flink. «self» greift in jedem Kampf an, falls möglich.", fr = "Rapide. «self» attaque à chaque combat si possible.", es = "Rápida. «self» ataca en cada combate si puede.", zh = "迅捷。如果可以，«self»每次战斗都必须攻击。", it = "Rapida. «self» attacca in ogni combattimento, se può." },
    { en = "Vigilant. When Duke Nicholas Zverenhoff enters the battlefield, deal 3 damage to each enemy Undead.", de = "Wachsam. Wenn «self» ins Spiel kommt, füge jedem gegnerischen Untoten 3 Schaden zu.", fr = "Vigilant. Quand «self» arrive sur le champ de bataille, infligez 3 points de dégâts à chaque Mort-vivant adverse.", es = "Vigilante. Cuando «self» entre al campo de batalla, inflige 3 de daño a cada No-muerto enemigo.", zh = "警戒。当«self»进入战场时，对每个敌方亡灵造成3点伤害。", it = "Vigile. Quando «self» entra nel campo di battaglia, infliggi 3 danni a ogni Non Morto avversario." },
