    { en = "When Lord Hel'nurath enters the battlefield, deal 3 damage to the opponent. Other Demons you control get +1/+1.", de = "Wenn «self» ins Spiel kommt, füge dem Gegner 3 Schaden zu. Deine anderen Dämonen erhalten +1/+1.", fr = "Quand «self» arrive sur le champ de bataille, infligez 3 points de dégâts à l'adversaire. Les autres Démons que vous contrôlez gagnent +1/+1.", es = "Cuando «self» entre al campo de batalla, inflige 3 de daño al oponente. Tus otros Demonios obtienen +1/+1.", zh = "当«self»进入战场时，对对手造成3点伤害。你操控的其他恶魔获得+1/+1。", it = "Quando «self» entra nel campo di battaglia, infliggi 3 danni all'avversario. Gli altri Demoni che controlli ottengono +1/+1." },
    { en = "When Lotwil Veriatus enters the battlefield, deal 1 damage to each enemy creature. Other Badlands creatures you control get +1/+0.", de = "Wenn «self» ins Spiel kommt, füge jeder gegnerischen Kreatur 1 Schaden zu. Deine anderen Kreaturen aus «zone:Badlands» erhalten +1/+0.", fr = "Quand «self» arrive sur le champ de bataille, infligez 1 point de dégâts à chaque créature adverse. Les autres créatures de «zone:Badlands» que vous contrôlez gagnent +1/+0.", es = "Cuando «self» entre al campo de batalla, inflige 1 de daño a cada criatura enemiga. Tus otras criaturas de «zone:Badlands» obtienen +1/+0.", zh = "当«self»进入战场时，对每个敌方生物造成1点伤害。你操控的其他«zone:Badlands»生物获得+1/+0。", it = "Quando «self» entra nel campo di battaglia, infliggi 1 danno a ogni creatura avversaria. Le altre creature di «zone:Badlands» che controlli ottengono +1/+0." },
    { en = "When Magistrate Solomon enters the battlefield, you gain 3 life. Other Redridge Mountains creatures you control get +0/+2.", de = "Wenn «self» ins Spiel kommt, erhältst du 3 Leben. Deine anderen Kreaturen aus «zone:Redridge Mountains» erhalten +0/+2.", fr = "Quand «self» arrive sur le champ de bataille, vous gagnez 3 points de vie. Les autres créatures de «zone:Redridge Mountains» que vous contrôlez gagnent +0/+2.", es = "Cuando «self» entre al campo de batalla, ganas 3 de vida. Tus otras criaturas de «zone:Redridge Mountains» obtienen +0/+2.", zh = "当«self»进入战场时，你获得3点生命。你操控的其他«zone:Redridge Mountains»生物获得+0/+2。", it = "Quando «self» entra nel campo di battaglia, guadagni 3 punti vita. Le altre creature di «zone:Redridge Mountains» che controlli ottengono +0/+2." },
    { en = "When Marin Noggenfogger enters the battlefield, draw a card. Other Tanaris creatures you control get +1/+0.", de = "Wenn «self» ins Spiel kommt, ziehe eine Karte. Deine anderen Kreaturen aus «zone:Tanaris» erhalten +1/+0.", fr = "Quand «self» arrive sur le champ de bataille, piochez une carte. Les autres créatures de «zone:Tanaris» que vous contrôlez gagnent +1/+0.", es = "Cuando «self» entre al campo de batalla, roba una carta. Tus otras criaturas de «zone:Tanaris» obtienen +1/+0.", zh = "当«self»进入战场时，抓一张牌。你操控的其他«zone:Tanaris»生物获得+1/+0。", it = "Quando «self» entra nel campo di battaglia, pesca una carta. Le altre creature di «zone:Tanaris» che controlli ottengono +1/+0." },
    { en = "When Razorfen Totemic enters the battlefield, prevent the next 3 damage that would be dealt to you. Other Quilboar you control get +1/+1.", de = "Wenn «self» ins Spiel kommt, verhindere die nächsten 3 Schaden, die dir zugefügt würden. Deine anderen Stacheleber erhalten +1/+1.", fr = "Quand «self» arrive sur le champ de bataille, prévenez les 3 prochains points de dégâts qui vous seraient infligés. Les autres Hurans que vous contrôlez gagnent +1/+1.", es = "Cuando «self» entre al campo de batalla, evita los próximos 3 de daño que fueras a recibir. Tus otros Jabaespines obtienen +1/+1.", zh = "当«self»进入战场时，防止接下来将对你造成的3点伤害。你操控的其他野猪人获得+1/+1。", it = "Quando «self» entra nel campo di battaglia, previeni i prossimi 3 danni che ti verrebbero inflitti. Gli altri Verrospino che controlli ottengono +1/+1." },
    { en = "When Senir Whitebeard enters the battlefield, draw a card. Other Dun Morogh creatures you control get +1/+0.", de = "Wenn «self» ins Spiel kommt, ziehe eine Karte. Deine anderen Kreaturen aus «zone:Dun Morogh» erhalten +1/+0.", fr = "Quand «self» arrive sur le champ de bataille, piochez une carte. Les autres créatures de «zone:Dun Morogh» que vous contrôlez gagnent +1/+0.", es = "Cuando «self» entre al campo de batalla, roba una carta. Tus otras criaturas de «zone:Dun Morogh» obtienen +1/+0.", zh = "当«self»进入战场时，抓一张牌。你操控的其他«zone:Dun Morogh»生物获得+1/+0。", it = "Quando «self» entra nel campo di battaglia, pesca una carta. Le altre creature di «zone:Dun Morogh» che controlli ottengono +1/+0." },
    { en = "When Thundris Windweaver enters the battlefield, draw a card. Other Darkshore creatures you control get +0/+1.", de = "Wenn «self» ins Spiel kommt, ziehe eine Karte. Deine anderen Kreaturen aus «zone:Darkshore» erhalten +0/+1.", fr = "Quand «self» arrive sur le champ de bataille, piochez une carte. Les autres créatures de «zone:Darkshore» que vous contrôlez gagnent +0/+1.", es = "Cuando «self» entre al campo de batalla, roba una carta. Tus otras criaturas de «zone:Darkshore» obtienen +0/+1.", zh = "当«self»进入战场时，抓一张牌。你操控的其他«zone:Darkshore»生物获得+0/+1。", it = "Quando «self» entra nel campo di battaglia, pesca una carta. Le altre creature di «zone:Darkshore» che controlli ottengono +0/+1." },
    { en = "Whenever Amnennar attacks, tap target creature. That creature does not untap during its controller's next untap step.", de = "Immer wenn «self» angreift, tappe eine Kreatur deiner Wahl. Jene Kreatur enttappt im nächsten Enttappsegment ihres Beherrschers nicht.", fr = "Chaque fois que «self» attaque, engagez une créature ciblée. Cette créature ne se dégage pas lors de la prochaine étape de dégagement de son contrôleur.", es = "Siempre que «self» ataque, gira una criatura objetivo. Esa criatura no se endereza en el próximo paso de enderezar de su controlador.", zh = "每当«self»攻击时，横置目标生物。该生物在其操控者的下一个重置步骤中不会重置。", it = "Ogni volta che «self» attacca, tappa una creatura bersaglio. Quella creatura non stappa nel prossimo passo di stap del suo controllore." },
    { en = "Whenever Mutanus attacks, target opponent discards a card and loses 1 life.", de = "Immer wenn «self» angreift, wirft der Gegner eine Karte ab und verliert 1 Leben.", fr = "Chaque fois que «self» attaque, l'adversaire défausse une carte et perd 1 point de vie.", es = "Siempre que «self» ataque, el oponente descarta una carta y pierde 1 de vida.", zh = "每当«self»攻击时，对手弃一张牌并失去1点生命。", it = "Ogni volta che «self» attacca, l'avversario scarta una carta e perde 1 punto vita." },
    { en = "Whenever another creature dies, you draw a card.", de = "Immer wenn eine andere Kreatur stirbt, ziehst du eine Karte.", fr = "Chaque fois qu'une autre créature meurt, vous piochez une carte.", es = "Siempre que muera otra criatura, robas una carta.", zh = "每当另一个生物死亡时，你抓一张牌。", it = "Ogni volta che un'altra creatura muore, peschi una carta." },
    { en = "{2}{U}: Draw a card, then discard a card. Tortheldrin gains +1/+1 until end of turn.", de = "{2}{U}: Ziehe eine Karte und wirf dann eine Karte ab. «self» erhält bis zum Ende des Zuges +1/+1.", fr = "{2}{U} : piochez une carte, puis défaussez une carte. «self» gagne +1/+1 jusqu'à la fin du tour.", es = "{2}{U}: roba una carta y luego descarta una carta. «self» obtiene +1/+1 hasta el final del turno.", zh = "{2}{U}：抓一张牌，然后弃一张牌。«self»获得+1/+1直到回合结束。", it = "{2}{U}: pesca una carta, poi scarta una carta. «self» ottiene +1/+1 fino alla fine del turno." },
    { en = "{T}: Deal 2 damage to all opposing creatures.", de = "{T}: Füge allen gegnerischen Kreaturen 2 Schaden zu.", fr = "{T} : infligez 2 points de dégâts à toutes les créatures adverses.", es = "{T}: inflige 2 de daño a todas las criaturas enemigas.", zh = "{T}：对所有敌方生物造成2点伤害。", it = "{T}: infliggi 2 danni a tutte le creature avversarie." },
    { en = "{T}: Deal 2 damage to each opposing creature.", de = "{T}: Füge jeder gegnerischen Kreatur 2 Schaden zu.", fr = "{T} : infligez 2 points de dégâts à chaque créature adverse.", es = "{T}: inflige 2 de daño a cada criatura enemiga.", zh = "{T}：对每个敌方生物造成2点伤害。", it = "{T}: infliggi 2 danni a ogni creatura avversaria." },
    { en = "{T}: Put target tapped creature on top of its owner's library.", de = "{T}: Lege eine getappte Kreatur deiner Wahl oben auf die Bibliothek ihres Besitzers.", fr = "{T} : mettez une créature engagée ciblée au-dessus de la bibliothèque de son propriétaire.", es = "{T}: pon una criatura girada objetivo en la parte superior de la biblioteca de su propietario.", zh = "{T}：将目标横置的生物置于其拥有者的牌库顶。", it = "{T}: metti una creatura tappata bersaglio in cima al grimorio del suo proprietario." },
    { en = "{T}: Target opponent loses 2 life and you gain 2 life.", de = "{T}: Der Gegner verliert 2 Leben und du erhältst 2 Leben.", fr = "{T} : l'adversaire perd 2 points de vie et vous gagnez 2 points de vie.", es = "{T}: el oponente pierde 2 de vida y tú ganas 2 de vida.", zh = "{T}：对手失去2点生命，你获得2点生命。", it = "{T}: l'avversario perde 2 punti vita e tu guadagni 2 punti vita." },
}
